from functools import lru_cache

class Solution:
    def mergeStones(self, stones, k):
        n = len(stones)
        if (n - 1) % (k - 1):
            return -1
        pre = [0]
        for x in stones:
            pre.append(pre[-1] + x)

        @lru_cache(maxsize=None)
        def f(i, j, m):
            if i == j:
                return 0 if m == 1 else float('inf')
            res = float('inf')
            for mid in range(i, j, k - 1):
                left = f(i, mid, m - 1)
                if left == float('inf'):
                    continue
                right = f(mid + 1, j, 1)
                if right != float('inf'):
                    res = min(res, left + right)
            if m == 1:
                base = f(i, j, k)
                if base < float('inf'):
                    res = min(res, base + pre[j + 1] - pre[i])
            return res

        ans = f(0, n - 1, 1)
        return ans if ans != float('inf') else -1

