class Solution {
public:
    int mergeStones(vector<int>& stones, int k) {
        int n = stones.size();
        if ((n - 1) % (k - 1)) return -1;
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + stones[i];
        const long long INF = 1e18;
        vector<vector<vector<long long>>> memo(n, vector<vector<long long>>(n, vector<long long>(k + 1, -1)));
        function<long long(int,int,int)> f = [&](int i, int j, int m) -> long long {
            if (i == j) return m == 1 ? 0 : INF;
            long long &res = memo[i][j][m];
            if (res != -1) return res;
            res = INF;
            for (int mid = i; mid < j; mid += k - 1) {
                long long l = f(i, mid, m - 1);
                if (l >= INF) continue;
                long long r = f(mid + 1, j, 1);
                if (r < INF) res = min(res, l + r);
            }
            if (m == 1) {
                long long b = f(i, j, k);
                if (b < INF) res = min(res, b + pre[j + 1] - pre[i]);
            }
            return res;
        };
        long long ans = f(0, n - 1, 1);
        return ans >= INF ? -1 : (int)ans;
    }
};

