class Solution {
    private long[][][] memo;
    private long[] pre;
    private int k;
    private static final long INF = Long.MAX_VALUE / 4;

    public int mergeStones(int[] stones, int k) {
        int n = stones.length;
        if ((n - 1) % (k - 1) != 0) return -1;
        this.k = k;
        pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + stones[i];
        memo = new long[n][n][k + 1];
        for (long[][] a : memo) for (long[] b : a) java.util.Arrays.fill(b, -1);
        long ans = f(0, n - 1, 1);
        return ans >= INF ? -1 : (int) ans;
    }

    private long f(int i, int j, int m) {
        if (i == j) return m == 1 ? 0 : INF;
        if (memo[i][j][m] != -1) return memo[i][j][m];
        long res = INF;
        for (int mid = i; mid < j; mid += k - 1) {
            long l = f(i, mid, m - 1);
            if (l >= INF) continue;
            long r = f(mid + 1, j, 1);
            if (r < INF) res = Math.min(res, l + r);
        }
        if (m == 1) {
            long b = f(i, j, k);
            if (b < INF) res = Math.min(res, b + pre[j + 1] - pre[i]);
        }
        return memo[i][j][m] = res;
    }
}

