var mergeStones = function(stones, k) {
    const n = stones.length;
    if ((n - 1) % (k - 1) !== 0) return -1;
    const pre = [0];
    for (const x of stones) pre.push(pre[pre.length - 1] + x);
    const INF = Infinity;
    const memo = new Map();
    const key = (i, j, m) => (i * 31 + j) * 32 + m;
    const f = (i, j, m) => {
        if (i === j) return m === 1 ? 0 : INF;
        const kk = key(i, j, m);
        if (memo.has(kk)) return memo.get(kk);
        let res = INF;
        for (let mid = i; mid < j; mid += k - 1) {
            const l = f(i, mid, m - 1);
            if (l === INF) continue;
            const r = f(mid + 1, j, 1);
            if (r !== INF) res = Math.min(res, l + r);
        }
        if (m === 1) {
            const b = f(i, j, k);
            if (b !== INF) res = Math.min(res, b + pre[j + 1] - pre[i]);
        }
        memo.set(kk, res);
        return res;
    };
    const ans = f(0, n - 1, 1);
    return ans === INF ? -1 : ans;
};

