class Solution:
    def mergeStones(self, stones, k):
        n = len(stones)
        if (n - 1) % (k - 1):
            return -1
        pre = [0]
        for x in stones:
            pre.append(pre[-1] + x)
        INF = float('inf')
        dp = [[[INF] * (k + 1) for _ in range(n)] for _ in range(n)]
        for i in range(n):
            dp[i][i][1] = 0
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                for m in range(2, k + 1):
                    for mid in range(i, j, k - 1):
                        if dp[i][mid][m - 1] + dp[mid + 1][j][1] < dp[i][j][m]:
                            dp[i][j][m] = dp[i][mid][m - 1] + dp[mid + 1][j][1]
                if dp[i][j][k] < INF:
                    dp[i][j][1] = dp[i][j][k] + pre[j + 1] - pre[i]
        return dp[0][n - 1][1]

